const fin=id=>kact('kid_finish',{id},'أُرسلت لأبيك للاعتماد ⏳'),kprog=(id,n)=>kact('kid_progress',{id,amount:n},'سُجّل تقدمك ✔'),buy=id=>kact('kid_buy',{item_id:id},'أُرسل طلبك لأبيك بانتظار موافقته ⏳');
const setSt=(id,s,m)=>act('task_set',{id,status:s},m),delT=id=>ask('حذف هذه المهمة؟')&&act('task_del',{id},'حُذفت المهمة'),ordSet=(id,s)=>act('order_set',{id,status:s},s==='ok'?'تمت الموافقة 🎉':'رُفض الطلب وأُعيدت النقاط');
const delS=id=>ask('حذف هذه الجائزة؟')&&act('store_del',{id}),setAdv=()=>{const a=S.family.adventure,i=ADVS.indexOf(a);return act('set_adventure',{adventure:ADVS[(i+1)%ADVS.length]},'تم تحديد الوجهة')};
async function appr(id){const t=S.tasks.find(x=>x.id===id),m=mem(t.person_id),l0=lvl(m.xp).i,t0=tier(cnt(m,t.cat));
 try{await api('task_set',{id,status:'done'});await refresh();const m2=mem(t.person_id),l1=lvl(m2.xp).i,t1=tier(cnt(m2,t.cat));
 toast(l1>l0?'🎉 '+m2.name+' ارتقى إلى «'+lvl(m2.xp).name+'»':t1>t0?'🎖️ شارة «'+BADGES[t.cat]+'» '+TN[t1-1]+'!':'تم الاعتماد +'+t.xp+' نقطة')}catch(e){fail(e)}}
const UNITS=['دقيقة','ساعة','صفحة','كم','مرة','كوب ماء','تمرين','آية'],XPS=[5,10,15,20,25,30,40,50],QTY=[5,10,15,20,25,30,45,60,90,100];
const numOpts=(arr,cur)=>[...new Set([...arr,...(cur?[+cur]:[])])].sort((a,b)=>a-b).map(n=>`<option value="${n}" ${+cur===n?'selected':''}>${n}</option>`).join('');
const unitOpts=cur=>[...new Set([...UNITS,...(cur?[cur]:[])])].map(u=>`<option value="${esc(u)}" ${cur===u?'selected':''}>${esc(u)}</option>`).join('');
const catOpts=cur=>Object.keys(CATS).map(c=>`<option value="${c}" ${cur===c?'selected':''}>${CATS[c][0]} ${CATS[c][1]}</option>`).join('');
let tf={title:'',kid:'',xp:10,cat:'tidy',qty:'',unit:'',due:'',steps:[]};
const tfSync=()=>{if($('nt')){tf.title=v('nt');tf.kid=v('nk');tf.xp=+v('nx')||10;tf.cat=v('nc')||'tidy';tf.qty=v('ng');tf.unit=v('nu');tf.due=v('nd')}};
const tfStepAdd=()=>{tfSync();const x=($('nsx')?$('nsx').value:'').trim();if(!x)return toast('اكتب اسم الخطوة');if(tf.steps.length>=20)return toast('حتى 20 خطوة');tf.steps.push(x);if($('nsx'))$('nsx').value='';render()};
const tfStepDel=i=>{tfSync();tf.steps.splice(i,1);render()};
function taskForm(targets){return `<h2>أضف مهمة</h2><div class="card"><input id="nt" value="${esc(tf.title)}" placeholder="اسم المهمة"><div class="f2"><select id="nk">${targets.map(k=>`<option value="${k.id}" ${tf.kid===k.id?'selected':''}>${esc(k.name)}</option>`).join('')}${targets.length>1?`<option value="all" ${tf.kid==='all'?'selected':''}>الجميع</option>`:''}</select><select id="nx">${numOpts(XPS,tf.xp)}</select><select id="nc" style="grid-column:span 2">${catOpts(tf.cat)}</select><select id="ng"><option value="">بدون هدف عددي</option>${numOpts(QTY,tf.qty)}</select><select id="nu"><option value="">الوحدة</option>${unitOpts(tf.unit)}</select></div><div class="mute" style="margin-top:6px">تاريخ الاستحقاق (اختياري، يظهر في التقويم):</div><input id="nd" type="date" value="${esc(tf.due)}"><div class="mute" style="margin-top:6px">الخطوات (اختياري):</div>${tf.steps.map((x,i)=>`<div class="row sp"><span class="mute">☐ ${esc(x)}</span><button class="btn ghost sm" onclick="tfStepDel(${i})">حذف</button></div>`).join('')}<div class="row"><input id="nsx" placeholder="اسم الخطوة"><button class="btn sm" onclick="tfStepAdd()">+ خطوة</button></div><button class="btn sun" style="width:100%;margin-top:8px" onclick="addT()">أضف المهمة</button></div>`}
async function addT(){tfSync();const t=tf.title;if(!t)return toast('اكتب اسم المهمة');const k=tf.kid,ids=k==='all'?kidsOf().map(x=>x.id):[k];if(!ids[0])return toast('أضف ابنًا أولًا');if(tf.qty&&!tf.unit)return toast('اختر وحدة الهدف');
 try{await api('add_tasks',{person_ids:ids,tasks:[{title:t,xp:tf.xp,cat:tf.cat,target:tf.qty?+tf.qty:null,unit:tf.qty?tf.unit:null,due_on:tf.due||null,steps:tf.steps.length?tf.steps:null}]});toast('أُضيفت المهمة ✔');tf={title:'',kid:tf.kid,xp:10,cat:tf.cat,qty:'',unit:'',due:'',steps:[]};await refresh()}catch(e){fail(e)}}
const addS=()=>{const n=v('sn'),c=+v('sc');if(!n||!(c>0))return toast('أدخل الاسم والسعر');return act('store_add',{title:n,cost:c},'أُضيفت الجائزة')};
const addKid=()=>act('create_child',{name:v('cn'),age:v('ca'),emoji:v('ce'),username:v('cu'),password:$('cp').value},'تم إنشاء حساب الابن ✔');
const resetPw=id=>act('reset_child_password',{child_id:id,password:$('rp'+id).value},'تم تغيير كلمة المرور');
async function inv(){try{const r=await api('create_invite');$('invc').textContent=r.code}catch(e){fail(e)}}
