async function loadLib(){try{LB=await api('lib_state',{q:lq,cat:lcat,tag:ltag,kind:lkind,src:lsrc})}catch(e){fail(e)}}
const lact=async(fn,p,m)=>{try{await api(fn,p);if(m)toast(m);await loadLib();render()}catch(e){fail(e)}};
const isG=()=>mode==='adult'&&S.person.role==='guardian';
const tgtIds=()=>isG()?(lt==='all'||!lt?kidsOf().map(x=>x.id):[lt]):[S.person.id];
function lcard(l,ctx){const g=isG(),b=[],pr=l.kind==='program',days=pr?Math.max(0,...l.items.map(i=>i.day||0)):0;
 if(ctx!=='adm'&&ctx!=='rep')b.push(pr?`<button class="btn sm" onclick="pEnroll('${l.id}')">التحق بالبرنامج</button>`:l.kind==='bucket'?`<button class="btn sm" onclick="bAdopt('${l.id}')">أضف إلى أمنياتي</button>`:`<button class="btn sm" onclick="lApply('${l.id}')">طبّق على المهام</button>`);
 if(ctx==='pub'){if(!l.official)b.push(`<button class="btn ghost sm" onclick="lReport('${l.id}')">إبلاغ</button>`);b.push(`<button class="btn ghost sm" onclick="lCopy('${l.id}','personal')">نسخ لقوائمي</button>`);if(g)b.push(`<button class="btn ghost sm" onclick="lCopy('${l.id}','family')">نسخ لعائلتي</button>`)}
 if(ctx==='fam'||ctx==='mine'){b.push(`<button class="btn ghost sm" onclick="lEdit('${l.id}')">تعديل</button><button class="btn ghost sm" onclick="lPub('${l.id}')">نشر للعامة</button><button class="btn ghost sm" onclick="lDel('${l.id}')">حذف</button>`);if(ctx==='mine'&&g)b.push(`<button class="btn ghost sm" onclick="lCopy('${l.id}','family')">نسخ لعائلتي</button>`)}
 if(ctx==='mypub')b.push(`<button class="btn ghost sm" onclick="lDel('${l.id}')">حذف</button>`);
 if(ctx==='rep')b.push(`<button class="btn sm" onclick="aHide('${l.id}')">إخفاء</button><button class="btn ghost sm" onclick="aDismiss('${l.id}')">تجاهل البلاغات</button>`);
 if(ctx==='adm')b.push(`<button class="btn sm" onclick="lRev('${l.id}','approved')">✔ قبول</button><button class="btn ghost sm" onclick="lRev('${l.id}','rejected')">رفض</button><button class="btn ghost sm" onclick="lDel('${l.id}')">حذف</button>`);
 const st=l.scope==='public'&&l.status!=='approved'?`<span class="pill ${l.status==='rejected'?'':'w'}">${l.status==='pending'?'قيد المراجعة':'مرفوضة'}</span> `:'';
 const bd=[l.official?'<span class="pill g">رسمية</span>':l.verified?'<span class="pill g">موثّق ✓</span>':'',pr?`<span class="pill">برنامج • ${days} يومًا</span>`:l.kind==='bucket'?'<span class="pill">قائمة أمنيات</span>':'',l.reports?`<span class="pill">${l.reports} بلاغ</span>`:'',l.age_min>0?`<span class="pill w">${l.age_min}+ سنة</span>`:''].filter(Boolean).join(' ');
 const tg=(l.tags||[]).map(t=>`<button class="pill w" style="border:0;cursor:pointer" data-t="${esc(t)}" onclick="srchTag(this.dataset.t)">#${esc(t)}</button>`).join(' ');
 return `<div class="card"><div class="row"><div class="ico">${ci(l.cat)[0]}</div><div class="grow"><h3>${esc(l.title)}</h3><div class="mute">${st}${esc(l.author||'')} • ${l.items.length} ${pr?'جلسة':'مهام'}${l.scope==='public'&&l.status==='approved'?' • استُخدمت '+l.uses+' مرة':''}</div></div></div>${bd?`<div style="margin-top:6px">${bd}</div>`:''}${l.descr?`<div class="mute" style="margin-top:4px">${esc(l.descr)}</div>`:''}${tg?`<div style="margin-top:6px">${tg}</div>`:''}<details style="margin-top:6px"><summary class="mute" style="cursor:pointer">عرض ${pr?'الجلسات':'المهام'}</summary>${l.items.map(i=>`<div class="mute">• ${pr?'يوم '+i.day+': ':''}${esc(i.title)} (+${i.xp})${i.target?' — '+i.target+' '+esc(i.unit||''):''}</div>${(i.steps||[]).map(x=>`<div class="mute" style="margin-inline-start:16px">☐ ${esc(x.t)}</div>`).join('')}`).join('')}</details><div class="row wrap" style="margin-top:8px">${b.join('')}</div></div>`}
function libV(g){
 if(!LB)return '<div class="card mute">جارٍ التحميل…</div>';
 const subs=[['pub','اكتشف'],...(g?[['fam','عائلتي']]:[]),['mine','قوائمي']];if(!subs.find(x=>x[0]===lsub))lsub='pub';
 const list=lsub==='pub'?LB.public:lsub==='fam'?LB.family:LB.mine,kd=kidsOf(),opt=(a,v_,t)=>`<option value="${v_}" ${a===v_?'selected':''}>${t}</option>`;
 let h=`<h2>🧭 اكتشف</h2><div class="mute" style="margin-bottom:6px">قوائم وبرامج: من تصنيفك، ومن الآخرين، ومن المتخصصين.</div>`+TABS(lsub,subs).replace(/setAt/g,'setSub');
 h+=`<div class="row wrap" style="margin-bottom:8px">${g&&kd.length?`<span class="mute">على:</span><select id="ltg" style="width:auto" onchange="setLt(this.value)"><option value="all" ${lt==='all'?'selected':''}>كل الأبناء</option>${kd.map(k=>`<option value="${k.id}" ${lt===k.id?'selected':''}>${esc(k.name)}</option>`).join('')}</select>`:''}<span class="mute">بدء البرنامج:</span><input id="ls" type="date" value="${lsd||today()}" style="width:auto" onchange="setLsd(this.value)"></div>`;
 if(lsub==='pub')h+=`<div class="f2"><input id="lqv" value="${esc(lq)}" placeholder="ابحث"><select id="lc"><option value="">كل الأنواع</option>${Object.keys(CATS).map(c=>`<option value="${c}" ${lcat===c?'selected':''}>${CATS[c][0]} ${CATS[c][1]}</option>`).join('')}</select><select id="lk">${opt(lkind,'','قوائم وبرامج')}${opt(lkind,'list','قوائم فقط')}${opt(lkind,'program','برامج فقط')}${opt(lkind,'bucket','قوائم أمنيات فقط')}</select><select id="lsr">${opt(lsrc,'','كل المصادر')}${opt(lsrc,'expert','من المتخصصين')}${opt(lsrc,'community','من الآخرين')}</select></div><button class="btn sm" onclick="srch()">بحث</button>${LB.tags.length?`<div style="margin-top:6px">${LB.tags.map(t=>`<button class="btn ${ltag===t?'':'ghost'} sm" style="margin:2px" data-t="${esc(t)}" onclick="srchTag(this.dataset.t)">#${esc(t)}</button>`).join('')}</div>`:''}`;
 else h+=`<button class="btn sun" onclick="lNew()">+ قائمة أو برنامج جديد</button>`;
 if(ed)h+=edForm(g);
 h+=`<div style="margin-top:10px">`+(list.length?list.map(l=>lcard(l,lsub)).join(''):'<div class="card mute">لا نتائج هنا</div>')+`</div>`;
 if(lsub==='mine'&&LB.mypub.length)h+=`<h2>قوائمي المنشورة</h2>`+LB.mypub.map(l=>lcard(l,'mypub')).join('');
 return h}
const admV=()=>`<h2>🛡️ قوائم بانتظار المراجعة</h2>`+(LB&&LB.pending.length?LB.pending.map(l=>lcard(l,'adm')).join(''):'<div class="card mute">لا قوائم معلّقة</div>')+`<h2>🚩 قوائم مُبلَّغ عنها</h2>`+(LB&&LB.reported&&LB.reported.length?LB.reported.map(l=>lcard(l,'rep')).join(''):'<div class="card mute">لا بلاغات</div>');
const setSub=x=>{lsub=x;ed=null;render()};
async function srch(){lq=v('lqv');lcat=v('lc');lkind=v('lk');lsrc=v('lsr');await loadLib();render()}
async function srchTag(t){ltag=ltag===t?'':t;await loadLib();render()}
const SUGG=['جري','لياقة','قراءة','عادات','أطفال','دراسة','صحة','رمضان'];
const edNorm=()=>{ed.items=ed.items||[];ed.tags=Array.isArray(ed.tags)?ed.tags:[];ed.kind=ed.kind||'list';ed.cat=ed.cat||'tidy';ed.age_min=+ed.age_min||0;ed.dr=ed.dr||{title:'',xp:10,target:'',unit:'',day:1}};
const lNew=()=>{ed={title:'',cat:'tidy',kind:'list',age_min:0,tags:[],items:[],dr:{title:'',xp:10,target:'',unit:'',day:1}};render()};
function edSync(){if(!ed||!$('ft'))return;ed.title=v('ft');ed.cat=v('fc')||ed.cat;ed.descr=v('fd');if($('fa'))ed.age_min=+v('fa')||0;if(!ed.id&&$('fk'))ed.kind=v('fk')||'list';if($('fs'))ed.scope=v('fs')||ed.scope;
 if($('it'))ed.dr={title:v('it'),xp:+v('ix')||10,target:v('iq'),unit:v('iu'),day:($('idy')?+v('idy'):0)||(ed.dr&&ed.dr.day)||1}}
function edKind(){edSync();if(ed.kind==='program'){ed.items.forEach((x,i)=>{if(!x.day)x.day=i+1});ed.dr.day=Math.max(0,...ed.items.map(x=>x.day||0))+1}render()}
function edAdd(){edSync();const d=ed.dr;if(!d.title)return toast('اكتب اسم المهمة');if(d.target&&!d.unit)return toast('اختر وحدة الهدف');
 const lim=ed.kind==='program'?60:30;if(ed.items.length>=lim)return toast('الحد الأقصى '+lim+' مهمة');
 ed.items.push({title:d.title,xp:d.xp,target:d.target?+d.target:null,unit:d.target?d.unit:null,day:ed.kind==='program'?d.day:null,steps:[]});
 ed.dr={title:'',xp:d.xp,target:d.target,unit:d.unit,day:ed.kind==='program'?d.day+1:1};render()}
const edDel=i=>{edSync();ed.items.splice(i,1);render()};
function edStepAdd(i){edSync();const x=($('sx'+i)?$('sx'+i).value:'').trim();if(!x)return toast('اكتب اسم الخطوة');if(ed.items[i].steps.length>=20)return toast('حتى 20 خطوة');ed.items[i].steps.push({t:x});if($('sx'+i))$('sx'+i).value='';render()}
const edStepDel=(i,j)=>{edSync();ed.items[i].steps.splice(j,1);render()};
const edTag=t=>{edSync();const a=ed.tags,k=a.indexOf(t);if(k>-1)a.splice(k,1);else if(a.length<5)a.push(t);else toast('خمسة وسوم كحد أقصى');render()};
function edTagNew(){edSync();const x=($('ftn')?$('ftn').value:'').trim().slice(0,20);if(!x)return toast('اكتب الوسم');if(!ed.tags.includes(x)){if(ed.tags.length>=5)return toast('خمسة وسوم كحد أقصى');ed.tags.push(x)}if($('ftn'))$('ftn').value='';render()}
function edForm(g){edNorm();const pr=ed.kind==='program',dr=ed.dr,tg=[...new Set([...ed.tags,...(LB&&LB.tags||[]),...SUGG])].slice(0,16);
 const dayOpts=numOpts(Array.from({length:120},(_,i)=>i+1),dr.day);
 return `<div class="card" style="margin-top:10px"><h3>${ed.id?'تعديل':'جديد'}: ${pr?'برنامج مجدول':ed.kind==='bucket'?'قائمة أمنيات':'قائمة'}</h3><input id="ft" value="${esc(ed.title||'')}" placeholder="العنوان"><div class="f2"><select id="fc">${catOpts(ed.cat)}</select>${ed.id?'<span></span>':`<select id="fk" onchange="edKind()"><option value="list" ${ed.kind==='list'?'selected':''}>قائمة</option><option value="program" ${pr?'selected':''}>برنامج مجدول</option><option value="bucket" ${ed.kind==='bucket'?'selected':''}>قائمة أمنيات</option></select>`}${ed.id?'':`<select id="fs"><option value="personal" ${(ed.scope||(lsub==='fam'?'family':'personal'))!=='family'?'selected':''}>شخصية</option>${g?`<option value="family" ${(ed.scope||(lsub==='fam'?'family':'personal'))==='family'?'selected':''}>عائلية</option>`:''}</select>`}<select id="fa">${[0,6,12,16,18].map(a=>`<option value="${a}" ${ed.age_min===a?'selected':''}>${a?a+'+ سنة':'مناسبة للجميع'}</option>`).join('')}</select></div><input id="fd" value="${esc(ed.descr||'')}" placeholder="وصف قصير (اختياري)">
 <div class="mute" style="margin-top:8px">الوسوم (اختر أو أضف):</div><div>${tg.map(t=>`<button class="btn ${ed.tags.includes(t)?'':'ghost'} sm" style="margin:2px" data-t="${esc(t)}" onclick="edTag(this.dataset.t)">${ed.tags.includes(t)?'✓ ':''}#${esc(t)}</button>`).join('')}</div><div class="row" style="margin-top:4px"><input id="ftn" placeholder="وسم جديد"><button class="btn sm" onclick="edTagNew()">+ وسم</button></div>
 <h3 style="margin-top:12px">${pr?'جلسات البرنامج':'مهام القائمة'} (${ed.items.length})</h3>
 ${ed.items.map((x,i)=>`<div class="card"><div class="row sp"><span><b>${i+1}.</b> ${esc(x.title)} <span class="mute">+${x.xp}${x.day?' • يوم '+x.day:''}${x.target?' • '+x.target+' '+esc(x.unit||''):''}</span></span><button class="btn ghost sm" onclick="edDel(${i})">حذف</button></div>${(x.steps||[]).map((p,j)=>`<div class="row sp" style="margin-inline-start:14px"><span class="mute">☐ ${esc(p.t)}</span><button class="btn ghost sm" onclick="edStepDel(${i},${j})">حذف</button></div>`).join('')}<div class="row" style="margin-top:6px"><input id="sx${i}" placeholder="اسم خطوة (اختياري)"><button class="btn sm" onclick="edStepAdd(${i})">+ خطوة</button></div></div>`).join('')||'<div class="mute">لم تُضف مهام بعد.</div>'}
 <div class="note"><h3>إضافة ${pr?'جلسة':'مهمة'}</h3><input id="it" value="${esc(dr.title)}" placeholder="اسم ${pr?'الجلسة':'المهمة'}"><div class="f2"><select id="ix">${numOpts(XPS,dr.xp)}</select>${pr?`<select id="idy">${dayOpts}</select>`:'<span></span>'}<select id="iq"><option value="">بدون هدف عددي</option>${numOpts(QTY,dr.target)}</select><select id="iu"><option value="">الوحدة</option>${unitOpts(dr.unit)}</select></div><div class="mute">النقاط${pr?'، واليوم (1 = يوم البدء)':''}، والهدف والوحدة: كلها اختيار.</div><button class="btn sun" style="width:100%;margin-top:6px" onclick="edAdd()">+ إضافة إلى القائمة</button></div>
 <div class="row" style="margin-top:8px"><button class="btn sun" onclick="lSave()">حفظ</button><button class="btn ghost" onclick="edCancel()">إلغاء</button></div></div>`}
function lEdit(id){const l=[...LB.mine,...LB.family].find(x=>x.id===id);ed={id,title:l.title,cat:l.cat,descr:l.descr,kind:l.kind,age_min:l.age_min,tags:[...(l.tags||[])],items:l.items.map(i=>({title:i.title,xp:i.xp,target:i.target,unit:i.unit,day:i.day,steps:(i.steps||[]).map(x=>({t:x.t}))})),dr:{title:'',xp:10,target:'',unit:'',day:Math.max(0,...l.items.map(i=>i.day||0))+1}};render()}
