 const p={id:ed.id,title:ed.title,cat:ed.cat,descr:ed.descr,scope:ed.id?undefined:(ed.scope||(lsub==='fam'?'family':'personal')),kind:ed.id?undefined:ed.kind,age_min:ed.age_min,tags:ed.tags,items:ed.items.map(x=>({title:x.title,xp:x.xp,target:x.target,unit:x.unit,day:x.day,steps:(x.steps||[]).map(s=>s.t)}))};
