const tog=id=>{cfSync();sel.has(id)?sel.delete(id):sel.add(id);render()},togM=id=>{selM.has(id)?selM.delete(id):selM.add(id);inReq?reqV():render()},setCsub=async x=>{csub=x;if(x==='camp')await loadCamp();render()};
function compV(){
 if(!CS||!FR)return '<div class="card mute">جارٍ التحميل…</div>';const me=S.person.id;
 let h='<h2>🏆 المنافسة</h2>'+TABS(csub,[['camp','حملات الأسبوع'],['ch','تحدياتي'],['fr','الأصدقاء']]).replace(/setAt/g,'setCsub');
 if(csub==='camp')return h+campV();
 if(csub==='ch'){const fm=new Map();FR.friends.forEach(f=>fm.set(f.friend,{id:f.friend,name:f.name,emoji:f.emoji,label:f.label}));
  h+=`<div class="card"><h3>تحدٍّ جديد</h3><input id="ct" value="${esc(cf.title||'')}" placeholder="مثال: من يقرأ أكثر هذا الأسبوع؟"><div class="f2"><select id="cmt" onchange="cfSync();render()"><option value="xp" ${cf.metric==='xp'?'selected':''}>بالنقاط</option><option value="tasks" ${cf.metric==='tasks'?'selected':''}>بعدد المهام</option><option value="count" ${cf.metric==='count'?'selected':''}>بالعدد (صفحات، دقائق…)</option></select><select id="cd">${[7,14,30].map(d=>`<option value="${d}" ${+cf.days===d?'selected':''}>${d} يومًا</option>`).join('')}</select>${cf.metric==='count'?`<select id="cu"><option value="">الوحدة</option>${unitOpts(cf.unit)}</select>`:''}<select id="cc"><option value="">كل الأنواع</option>${Object.keys(CATS).map(c=>`<option value="${c}" ${cf.cat===c?'selected':''}>${CATS[c][0]} ${CATS[c][1]}</option>`).join('')}</select></div><div class="mute" style="margin-top:6px">المشاركون من عائلتك:</div>${chips(FR.managed,sel,'tog')}${fm.size?`<div class="mute" style="margin-top:6px">أصدقاؤك (يدخلون بموافقة أولياء أمورهم):</div>${chips([...fm.values()],sel,'tog')}`:'<div class="mute" style="margin-top:6px">أضف أصدقاء من تبويب «الأصدقاء» لتدعوهم.</div>'}<button class="btn sun" style="width:100%;margin-top:8px" onclick="chNew()">إنشاء التحدي</button></div>`;
  h+=CS.items.length?CS.items.map(c=>chCard(c,me)).join(''):'<div class="card mute">لا تحديات بعد</div>'}
 else{
  h+=`<div class="card"><h3>🔗 رابط الإضافة</h3><div class="note" style="word-break:break-all;margin:6px 0">${base()}?add=${esc(FR.code)}</div><button class="btn sm" onclick="copyLink()">نسخ الرابط</button><div class="mute" style="margin-top:6px">أرسله لقريبك أو صديقك. لا يُضاف أحد إلا بموافقة ولي أمر كل ابن.</div></div>`;
  if(FR.incoming.length)h+=`<h2>طلبات صداقة <span class="pill">${FR.incoming.length}</span></h2>`+FR.incoming.map(r=>`<div class="card"><h3>${esc(r.label)} يريد إضافتكم</h3><div class="mute">سيُضاف: ${r.members.map(m=>esc(m.emoji)+' '+esc(m.name)).join('، ')}</div>${pickM()}<div class="row" style="margin-top:8px"><button class="btn" onclick="frResp('${r.id}',true)">قبول</button><button class="btn ghost" onclick="frResp('${r.id}',false)">رفض</button></div></div>`).join('');
  if(FR.outgoing.length)h+=`<h2>طلبات أرسلتها</h2>`+FR.outgoing.map(r=>`<div class="card row sp"><span>${esc(r.label)}</span><span class="row"><span class="pill w">بانتظار الموافقة</span><button class="btn ghost sm" onclick="frCancel('${r.id}')">إلغاء</button></span></div>`).join('');
  h+=`<h2>الأصدقاء</h2>`+(FR.friends.length?FR.friends.map(f=>{const m=FR.managed.find(x=>x.id===f.mine);return `<div class="card row sp"><span>${esc(m?m.name:'')} ⟷ ${esc(f.emoji)} <b>${esc(f.name)}</b> <span class="mute">${esc(f.label)}</span></span><button class="btn ghost sm" onclick="frDel('${f.mine}','${f.friend}')">إزالة</button></div>`}).join(''):'<div class="card mute">لا أصدقاء بعد. شارك رابطك أو افتح رابط صديق.</div>')}
 return h}
let inReq=false;
const clrAdd=()=>{inReq=false;ADD=null;if(typeof history!=='undefined'&&typeof location!=='undefined')history.replaceState(null,'',location.pathname)};
function reqV(){inReq=true;shell(1);$('view').innerHTML=`<h2>🤝 طلب صداقة</h2><div class="card"><h3>${esc(FQ.label)}</h3>${FR.managed.length===1?'<div class="mute" style="margin:4px 0 8px">سيُضاف حسابك أنت بعد موافقة الطرف الآخر ✓</div>':`<div class="mute" style="margin:4px 0 8px">من تريد إضافته من عائلتك؟ لا يُضاف أي ابن إلا باختيارك أنت، وبعد موافقة الطرف الآخر.</div>${chips(FR.managed,selM,'togM')}`}<div class="row" style="margin-top:10px"><button class="btn sun" onclick="frSend()">إرسال الطلب</button><button class="btn ghost" onclick="reqCancel()">إلغاء</button></div></div>`}
