const ymd=d=>d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0'),today=()=>ymd(new Date());
const WD=['أحد','اثنين','ثلاثاء','أربعاء','خميس','جمعة','سبت'],WSAT=[6,0,1,2,3,4,5],MN=['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];
const HPACKS=[{n:'عادات الصباح',h:[['أذكار الصباح','faith',5],['ترتيب السرير','tidy',3],['كوب ماء عند الاستيقاظ','fit',2]]},{n:'عادات الدراسة',h:[['مراجعة 20 دقيقة','read',5],['تجهيز الحقيبة للغد','tidy',3]]},{n:'عادات الصحة',h:[['مشي أو رياضة 15 دقيقة','fit',5],['النوم مبكرًا','fit',3]]},{n:'عادات القرب من الله',h:[['صلاة الفجر','faith',5],['ورد القرآن','faith',5],['أذكار المساء','faith',3]]}];
let HB=null,CAL=null,hsub='today',cm=today().slice(0,7)+'-01',cday=null,cpf='all',hd={title:'',cat:'tidy',xp:5},hwd=new Set([0,1,2,3,4,5,6]),hna=false,hsel=new Set(),hid=null,hinit=false;
