const hChk=id=>hact('habit_check',{id,day:today()}),hDel=id=>ask('حذف هذه العادة؟ النقاط التي اكتُسبت تبقى.')&&hact('habit_del',{id},'حُذفت العادة'),hRev=(id,day,ok)=>hact('habit_review',{id,day,approve:ok},ok?'تم الاعتماد ✔':'رُفضت'),hDay=(pid,day)=>hact('habit_approve_day',{person_id:pid,day},'اعتُمد اليوم كله ✔'),kHab=id=>hact('kid_habit_check',{token:kt(),id,day:today()});
const habPendCard=()=>S.habit_pending>0?`<div class="card row sp"><span>🌱 عادات بانتظار اعتمادك</span><span class="row"><span class="pill">${S.habit_pending}</span><button class="btn sm" onclick="go('hab')">افتح</button></span></div>`:'';
const wdText=h=>h.weekdays.length===7?'يوميًا':h.weekdays.map(d=>WD[d]).join('، ');
function wk(h){const L=HB.logs.filter(l=>l.habit_id===h.id);let r='';for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const k=ymd(d),sc=h.weekdays.includes(d.getDay()),lg=L.find(l=>l.day===k);r+=`<i class="${!sc?'u':lg?(lg.status==='done'?'d':'p'):i===0?'':'m'}"></i>`}return `<span class="wk">${r}</span>`}
function hrow(h){const st=h.today;return `<div class="card"><div class="row sp"><div class="grow"><b>${esc(h.title)}</b><div class="mute">${ci(h.cat)[0]} +${h.xp} • ${h.needs_approval?'باعتماد':'تلقائية'} • ${wdText(h)}</div>${wk(h)}</div><div style="text-align:center"><div class="fire">🔥 ${h.streak}</div><button class="btn sm ${st==='none'?'':'ghost'}" onclick="hChk('${h.id}')">${st==='done'?'✓ تم':st==='pending'?'اعتماد':'سجّل'}</button></div></div><div class="row" style="margin-top:6px"><button class="btn ghost sm" onclick="hEdit('${h.id}')">تعديل</button><button class="btn ghost sm" onclick="hDel('${h.id}')">حذف</button></div></div>`}
function hpend(){const P=HB.pending;if(!P.length)return '';const by={};P.forEach(x=>(by[x.person_id+'|'+x.day]=by[x.person_id+'|'+x.day]||[]).push(x));
 return `<h2>بانتظار اعتمادك <span class="pill">${P.length}</span></h2>`+Object.values(by).map(a=>`<div class="card"><div class="row sp"><span><b>${esc(a[0].person)}</b> <span class="mute">${a[0].day}</span></span><button class="btn sm" onclick="hDay('${a[0].person_id}','${a[0].day}')">اعتماد اليوم كله</button></div>${a.map(x=>`<div class="row sp" style="margin-top:6px"><span>${esc(x.title)}</span><span class="row"><button class="btn sm" onclick="hRev('${x.habit_id}','${x.day}',true)">✔</button><button class="btn ghost sm" onclick="hRev('${x.habit_id}','${x.day}',false)">✖</button></span></div>`).join('')}</div>`).join('')}
const hSync=()=>{if($('ht')){hd.title=v('ht');hd.cat=v('hc');hd.xp=+v('hx')}},togW=d=>{hSync();hwd.has(d)?hwd.delete(d):hwd.add(d);render()},togNa=()=>{hSync();hna=!hna;render()},togH=id=>{hSync();hsel.has(id)?hsel.delete(id):hsel.add(id);render()};
function hform(g){if(!hinit&&!hid){const kd=HB.people.filter(p=>g&&p.id!==S.person.id);(kd.length?kd:HB.people).forEach(p=>hsel.add(p.id));hinit=true}
 return `<div class="card"><input id="ht" value="${esc(hd.title)}" placeholder="مثال: أذكار الصباح"><div class="f2"><select id="hc">${Object.keys(CATS).map(c=>`<option value="${c}" ${hd.cat===c?'selected':''}>${CATS[c][0]} ${CATS[c][1]}</option>`).join('')}</select><select id="hx">${[0,1,2,3,5,10].map(x=>`<option value="${x}" ${hd.xp===x?'selected':''}>${x} نقاط لكل يوم</option>`).join('')}</select></div><div class="mute" style="margin-top:6px">أيام العادة:</div><div>${WSAT.map(d=>`<button class="btn ${hwd.has(d)?'':'ghost'} sm" style="margin:2px" onclick="togW(${d})">${hwd.has(d)?'✓ ':''}${WD[d]}</button>`).join('')}</div>${g?`<div style="margin-top:6px"><button class="btn ${hna?'':'ghost'} sm" onclick="togNa()">${hna?'✓ ':''}تحتاج اعتمادك</button> <span class="mute">${hna?'لن تُحسب النقاط حتى تعتمد':'تُحسب تلقائيًا'}</span></div>`:''}${hid?'':`<div class="mute" style="margin-top:6px">لمن؟</div><div>${chips(HB.people.map(p=>({id:p.id,name:p.name,emoji:p.emoji})),hsel,'togH')}</div>`}<div class="row" style="margin-top:8px"><button class="btn sun" onclick="hSave()">${hid?'حفظ التعديل':'أضف العادة'}</button>${hid?'<button class="btn ghost" onclick="hCancel()">إلغاء</button>':''}</div></div>`}
function hEdit(id){const h=HB.habits.find(x=>x.id===id);hid=id;hd={title:h.title,cat:h.cat,xp:h.xp};hwd=new Set(h.weekdays);hna=h.needs_approval;render();scrollTo(0,document.body.scrollHeight)}
