 let cells='';for(let i=0;i<off;i++)cells+='<div class="cell e"></div>';
 for(let d=1;d<=n;d++){const o=info(d);cells+=`<button class="cell ${o.k===td?'td':''} ${o.k===sel?'sel':''}" onclick="selDay('${o.k}')">${d}<div>${o.t.length?'<span class="dt t"></span>':''}${o.lg.some(l=>l.status==='done')?'<span class="dt h"></span>':''}${o.lg.some(l=>l.status==='pending')?'<span class="dt p"></span>':''}${o.ch.length?'<span class="dt c"></span>':''}</div></button>`}
